            unload = 1;
        }
    }
    if (unload) {
        adcs_status_t st = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit,
                                                       command, torque);
        if (st != ADCS_OK) {
            *enabled = 0;
            *excess = 0.0;
